-- Thread 1 (sort 292): eliyahu-prophet-pattern-and-promised-return-in-sirach-48
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'eliyahu-prophet-pattern-and-promised-return-in-sirach-48',
       'The Eliyahu-pattern prophet''s zeal and promised return — Sirach (Ecclesiasticus) 48',
       'Matt 14:1-12''s beheading of Yochanan (John) the Witness at Herod-Antipas''s hand — *Herod had laid hold on Yochanan (John), and bound him, and put him in prison for Herodias'' sake, his brother Philip''s wife. For Yochanan (John) said unto him, It is not lawful for thee to have her* — read against the wisdom-stream''s direct articulation of the Eliyahu-pattern prophet''s-fiery-zeal-at-the-royal-court and promised-return architecture. Four moves: Sirach (Ecclesiasticus) 48:1 names *then stood up Eliyahu (Elias) the prophet as fire, and his word burned like a lamp* (the prophet''s-fiery-zeal at the Achav (Ahab)-Yezevel (Jezebel) royal-court); Sirach 48:2 names *who brought a sore famine upon them, and by his zeal he diminished their number* (the Eliyahu-pattern judgment-on-the-Torah-violating-court); Sirach 48:10 names THE direct verbal-anchor for the Malakhi (Malachi) 4:5-6 promised-return — *who wast ordained for reproofs in their times ... and to turn the heart of the father unto the son, and to restore the tribes of Ya''aqov (Jacob)* (the framework reads in two-fold structure per voice-skill: Yochanan (John) the first-Eliyahu-coming preparing for the King''s-first-arrival; the eschatological-second-Eliyahu of Revelation 11 preparing for the second-coming); Sirach 48:11 names *blessed are they that saw thee, and slept in love; for we shall surely live* (the prophet''s-disciples-blessed pattern Yochanan (John)''s-disciples enact at v.12''s burial-and-going-to-tell-Yahusha (Jesus)). The framework reads the cluster as the wisdom-stream''s direct articulation of the Eliyahu-pattern architecture the Tanakh established (1 Melakhim (Kings) 17-22; 2 Melakhim (Kings) 1-2) and Malakhi (Malachi) 4:5-6 promised. The Achav-Yezevel-Torah-violation-architecture recapitulates at the Herod-Antipas / Herodias level; the Eliyahu-pattern prophet''s-confrontation-of-the-unrighteous-ruler operates in continuity across the Tanakh, the wisdom-stream, and the gospel. The restoration-of-the-tribes-of-Ya''aqov (Jacob) substance of Sirach 48:10 is the framework''s scattered-seed-gathering-architecture the wisdom-stream knew at the Eliyahu-pattern register.',
       sv.verse_id, ev.verse_id, 'complete_study', 292
  FROM _s144_verse_lookup sv, _s144_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 14 AND sv.verse_number = 1
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 14 AND ev.verse_number = 12
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 293): wilderness-manna-and-bread-as-word-in-wisdom-of-solomon-and-2-esdras-and-sirach
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'wilderness-manna-and-bread-as-word-in-wisdom-of-solomon-and-2-esdras-and-sirach',
       'The wilderness-manna and the bread-of-life as Word-of-Yahuah — Wisdom of Solomon 16, 2 Esdras 1, and Sirach (Ecclesiasticus) 24',
       'Matt 14:13-21''s feeding-of-the-five-thousand at the Galilee-desert-place — *and Yahusha (Jesus) went forth, and saw a great multitude, and was moved with compassion toward them, and he healed their sick ... took the five loaves, and the two fishes, and looking up to heaven, he blessed, and brake, and gave the loaves to his disciples, and the disciples to the multitude. And they did all eat, and were filled* — read against the wisdom-stream''s direct articulation of the wilderness-manna and the bread-from-heaven-as-Word-of-Yahuah architecture. Four moves: 2 Esdras (4 Ezra) 1:19 names the wilderness-manna in the prophetic-recap — *I gave you angels'' food to eat in your hunger* (the Father''s-wilderness-feeding-of-the-multitude substance); Wisdom of Solomon 16:20 names THE direct verbal-anchor — *thou feddest thine own people with angels'' food, and didst send them from heaven bread prepared without their labour, able to content every man''s delight*; Wisdom of Solomon 16:26 names the bread-of-life-is-the-Word substance — *it is not the growing of fruits that nourisheth man: but that it is thy word, which preserveth them that put their trust in thee*; Sirach (Ecclesiasticus) 24:19 names the wisdom-feeding-her-children invitation — *come unto me, all ye that be desirous of me, and fill yourselves with my fruits.* The framework reads the cluster as the wisdom-stream''s direct articulation of the Father''s-wilderness-feeding architecture (Shemot (Exodus) 16) AND the bread-as-Word substance the Yochanan (John) 6 bread-of-life discourse explicitly anchors (John 6:32-35, 6:48-51, 6:63). The King at Matt 14:13-21 recapitulates the wilderness-manna without mediation (vs Mosheh (Moses)-mediated at Shemot 16) and exceeds Elisha''s-feeding-of-the-hundred (2 Melakhim (Kings) 4:42-44) at the Galilee-desert-place; the twelve-baskets-leftover signal the twelve-tribes-restoration-architecture; the substance points beyond-the-loaves to the Word-of-the-King the disciples are being trained to receive as the bread-from-heaven the wisdom-stream had named the Father-feeding-his-people-with. The wisdom-stream knew the architecture at multiple registers; the King names the operative-form at the gospel-pivot.',
       sv.verse_id, ev.verse_id, 'complete_study', 293
  FROM _s144_verse_lookup sv, _s144_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 14 AND sv.verse_number = 13
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 14 AND ev.verse_number = 21
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 294): wonders-of-the-sea-and-the-creators-mastery-in-sirach-and-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'wonders-of-the-sea-and-the-creators-mastery-in-sirach-and-wisdom-of-solomon',
       'Wonders of the sea and the Creator''s mastery — Sirach (Ecclesiasticus) 43 and Wisdom of Solomon 14',
       'Matt 14:25''s King-walking-on-the-sea in the fourth-watch — *and in the fourth watch of the night Yahusha (Jesus) went unto them, walking on the sea* — read against the wisdom-stream''s direct articulation of the Creator''s-mastery-of-the-deep architecture. Three moves: Sirach (Ecclesiasticus) 43:23 names *by his counsel he appeaseth the deep, and planteth islands therein* (the Creator''s-counsel-appeasing-the-deep); Sirach 43:25 names *for in it be strange and wondrous works, variety of all kinds of beasts and whales created* (the wonders-of-the-sea as the Creator''s-domain); Wisdom of Solomon 14:3 names *but thy providence, O Father, governeth it: for thou hast made a way in the sea, and a safe path in the waves.* The framework reads the cluster as the wisdom-stream restatement of the Tanakh''s-direct-Yahuah-substance the King''s walking-on-the-sea enacts (Iyov (Job) 9:8 — *which alone spreadeth out the heavens, and treadeth upon the waves of the sea*; Tehillim (Psalm) 77:19 — *thy way is in the sea, and thy path in the great waters*; Habakkuk 3:15 — *thou didst walk through the sea with thine horses, through the heap of great waters*). The framework''s nature-of-God reading carries — the One who walks-upon-the-waves at Iyov (Job) 9:8 is the same One walking on the Galilee-sea in the fourth-watch; the wisdom-stream''s articulation of the Creator''s-mastery-of-the-deep (Sirach 43:23) + the Father''s-providence-making-a-way-in-the-sea (Wisdom 14:3) names the substance behind-the-action; the King''s walking-on-the-sea + the *it is I* / *egō eimi* self-identification at v.27 enacts the operative-form. The Formed-cloud-rider acts in the substance the Formless-Father''s-counsel established and the Father''s-providence-governs.',
       sv.verse_id, ev.verse_id, 'complete_study', 294
  FROM _s144_verse_lookup sv, _s144_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 14 AND sv.verse_number = 25
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 14 AND ev.verse_number = 25
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 295): ehyeh-self-identification-and-the-all-powerful-word-from-heaven-in-wisdom-and-sirach
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'ehyeh-self-identification-and-the-all-powerful-word-from-heaven-in-wisdom-and-sirach',
       'The Ehyeh self-identification and the all-powerful Word leaping down from heaven — Wisdom of Solomon 18, Sirach (Ecclesiasticus) 24, and Wisdom of Solomon 9 (FRAMEWORK-MAJOR)',
       'Matt 14:27''s *be of good cheer; it is I; be not afraid* (Greek *egō eimi*) at the walking-on-the-sea moment — read against the wisdom-stream''s direct articulation of the all-powerful-Word-leaping-down-from-heaven and the Wisdom-proceeding-from-the-mouth-of-the-most-High architecture. Three moves: Wisdom of Solomon 18:15 names THE direct verbal-anchor — *thine almighty word leaped down from heaven out of thy royal throne, as a fierce man of war into the midst of a land of destruction* (the all-powerful-Word from-the-Father''s-throne-coming-down-from-heaven); Sirach (Ecclesiasticus) 24:3 names *I came out of the mouth of the most High, and covered the earth as a cloud* (the Wisdom-proceeding-from-the-mouth-of-the-Formless-most-High with the cloud-covering-the-earth-substance); Wisdom of Solomon 9:1 names *O Elohim (God) of my fathers, and Yahuah (Lord) of mercy, who hast made all things with thy word* (the Word-as-the-Father''s-agent-of-creation). The framework reads the cluster as FRAMEWORK-MAJOR for the framework''s Formless-Formed nature-of-God reading. The Greek *egō eimi* is the LXX-equivalent of the Tanakh''s-Ehyeh (Shemot (Exodus) 3:14 — *Ehyeh asher Ehyeh* — *I AM THAT I AM*). The King''s *it is I* at v.27 is the Ehyeh-substance self-naming at the moment of walking-on-the-sea. The framework rules out the Jehovah''s-Witness-style flattening of *egō eimi* into mere-grammatical-self-reference without the divine-name-resonance. The wisdom-stream had named the architecture of the Formed-Word the Formless-Father expressed-from-the-beginning AND of the Word-as-agent-of-creation AND of the Wisdom-proceeding-from-the-mouth-of-the-most-High; the Yochanan (John) 1:14 *the Word was made flesh, and dwelt among us* names the substance-in-person; the King''s *it is I* across the dark water at the fourth-watch is the operative-form of the Word-from-heaven the wisdom-stream had named. The Formed-Word that proceeded from the Formless-Father in the Wisdom 18:15 + Sirach 24:3 + Wisdom 9:1 architecture is the speaker walking-on-the-water and naming-himself with the Ehyeh-substance. The framework reads this in continuity with the broader Yochanan (John) *egō eimi* sayings chain (John 6:35, 8:12, 10:7, 10:11, 11:25, 14:6, 15:1, and the load-bearing John 8:58''s *before Avraham (Abraham) was, I am*).',
       sv.verse_id, ev.verse_id, 'complete_study', 295
  FROM _s144_verse_lookup sv, _s144_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 14 AND sv.verse_number = 27
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 14 AND ev.verse_number = 27
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 296): righteous-witness-lied-in-wait-for-and-condemned-with-shameful-death-in-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'righteous-witness-lied-in-wait-for-and-condemned-with-shameful-death-in-wisdom-of-solomon',
       'The righteous witness lied in wait for and condemned with a shameful death — Wisdom of Solomon 2:10-20',
       'Matt 14:3-12''s Herod-Antipas / Herodias / Salome arrangement that produces Yochanan (John) the Witness''s beheading — *Herod had laid hold on Yochanan (John), and bound him ... For Yochanan (John) said unto him, It is not lawful for thee to have her ... when he would have put him to death, he feared the multitude ... she, being before instructed of her mother, said, Give me here Yochanan (John) the Immerser''s head in a charger ... And he sent, and beheaded Yochanan (John) in the prison* — read against the wisdom-stream''s direct articulation of the ungodly-determining-to-lie-in-wait-for-the-righteous-and-condemn-him-with-a-shameful-death architecture. Three moves: Wisdom of Solomon 2:12 names THE direct verbal-anchor — *therefore let us lie in wait for the righteous; because he is not for our turn, and he is clean contrary to our doings: he upbraideth us with our offending the law*; Wisdom of Solomon 2:19 names the disposition''s testing-pattern — *let us examine him with despitefulness and torture, that we may know his meekness, and prove his patience*; Wisdom of Solomon 2:20 names the disposition''s end-point — *let us condemn him with a shameful death.* The framework reads the cluster as the wisdom-stream''s prophetic-naming of the disposition the Herod-Antipas / Herodias / Salome arrangement enacts at vv.3-12. Yochanan (John) upbraided Herod with the Torah-violation (Vayikra (Leviticus) 18:16, 20:21); the ungodly determined to-lie-in-wait-for-the-righteous; the birthday-banquet-oath arrangement removed the political-restraint Herod''s-fear-of-the-multitude operated within; the shameful-death of the beheading-in-the-prison was the disposition''s end-point. The wisdom-stream had named the architecture centuries before; Matt 14:3-12 names the operative-form at the Herod-court-level. The framework reads the disposition in continuity with its other Tanakh-and-NT manifestations: the Pharisaic-plot at Matt 12:14, the Sanhedrin''s-arrangement of the King''s-trial at Matt 26:3-4, the broader Tanakh-prophet-killing pattern at 2 Chronicles 24:20-22 and Matt 23:34-37. One architecture; multiple costumes; the wisdom-stream named it.',
       sv.verse_id, ev.verse_id, 'complete_study', 296
  FROM _s144_verse_lookup sv, _s144_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 14 AND sv.verse_number = 3
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 14 AND ev.verse_number = 12
ON CONFLICT (slug) DO NOTHING;

